<script setup lang="ts">
const props=defineProps<{action:{id:string;token:string;summary:string;expiresAt:string|Date;kind:string}}>();const emit=defineEmits<{done:[result:{id:string;number:string}]}>();const {mutate}=useStaff();const busy=ref(false);const failure=ref('');const result=ref<{id:string;number:string}|null>(null);
async function confirm(){if(busy.value||result.value)return;busy.value=true;failure.value='';try{result.value=await mutate<{id:string;number:string}>(`/api/admin/assistant/actions/${props.action.id}/confirm`,{method:'POST',body:{token:props.action.token}});emit('done',result.value);}catch(e){failure.value=errorMessage(e);}finally{busy.value=false;}}
</script>
<template><section class="action-review"><span class="eyebrow">REVISA ANTES DE CONFIRMAR</span><h3>{{action.kind==='create'?'Crear esta solicitud':'Aplicar estos cambios'}}</h3><p class="preserve-lines action-summary">{{action.summary}}</p><p class="fine-print">Propuesta válida hasta {{new Date(action.expiresAt).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}}. Si cambian los datos, tendrás que revisarla de nuevo.</p><p v-if="failure" role="alert" class="field-error">{{failure}}</p><button v-if="!result" class="button dark full" :disabled="busy" @click="confirm">{{busy?'Guardando…':'Confirmar cambios'}}<AppIcon name="Check" :size="17"/></button><NuxtLink v-else :to="`/admin/solicitudes/${result.id}`" class="button lime full">Guardado · {{result.number}} <AppIcon name="ArrowRight" :size="16"/></NuxtLink></section></template>
